def main():
    hashes=json.loads(subprocess.check_output(['node','-e',"const fs=require('fs'),c=require('crypto'),m=JSON.parse(fs.readFileSync('johannesbergbuild/course-model.json'));let o={};function h(v){return c.createHash('sha256').update(JSON.stringify(v)).digest('hex')};for(let x of m.holes)o[x.n]={fairway:h(x.fairway.rings),tees:h(x.tees.pads.map(p=>p.ring))};process.stdout.write(JSON.stringify(o))"],cwd=ROOT,text=True))
    result=dict(schemaVersion=1,groundId='johannesberg',course='johannesberg',frame={k:MODEL[k] for k in ['origin','mPerLat','mPerLon']},reviewedOn='2026-09-09',features=[],unresolved=UNRESOLVED+[dict(holes=list(range(10,19)),kind='tee-marker-colours',reason='Physical tee turf is mapped; five-colour assignments and permanent measured tee points cannot be established reliably from these orthophotos.')])
    overlays={}
    for s in SPECS:
        window=f'eighteen-{s["hole"]:02d}-hole';meta=json.loads((CACHE/(window+'.json')).read_text('utf-8'))
        bounds=meta['boundsEpsg3006'];res=meta['resolutionMetres']
        rings=[]
        for ring in s['coords']:
            converted=[]
            for px,py in ring:
                lon,lat=INVERSE.transform(bounds[0]+px*res,bounds[3]-py*res)
                converted.append([round((lon-MODEL['origin']['lon'])*MODEL['mPerLon'],3),round((MODEL['origin']['lat']-lat)*MODEL['mPerLat'],3)])
            rings.append(converted)
        evidence=dict(sourceFiles=[dict(path='johannesbergbuild/cache/lm-ortho/'+meta['rasterFile'],sha256=meta['sha256']),dict(path='johannesbergbuild/cache/lm-ortho/'+meta['rgbFile'],sha256=meta['rgbSha256'])],sourceCaptureDates=sorted({x['capturedAt'][:10] for x in meta['sources']}),uncertaintyM=s['uncertainty'],note=s['note'],panelExtent=dict(crs='EPSG:3006',bounds=bounds),panelPixelSize=[meta['width'],meta['height']],sourcePixelRings=s['coords'],pixelConvention='pixel-edge coordinates: E=minE+x*resolution, N=maxN-y*resolution')
        f=dict(id=f'johannesberg-hole-{s["hole"]:02d}-{s["kind"]}',hole=s['hole'],kind=s['kind'],status='accepted',originalRingSha256=hashes[str(s['hole'])].get(s['kind']),rings=rings,evidence=evidence)
        if s['kind']=='tee':
            f.update(action='add',index=2,ring=rings[0],originalRingSha256=hashlib.sha256(b'null').hexdigest());del f['rings']
            evidence['sourcePixelRing']=evidence.pop('sourcePixelRings')[0]
        result['features'].append(f)
        if window not in overlays:overlays[window]=Image.open(CACHE/(window+'.png')).convert('RGB')
        d=ImageDraw.Draw(overlays[window]);color='#00ffff' if s['kind'] in ['tees','tee'] else '#ffee22'
        for ring in s['coords']:d.line([tuple(p) for p in ring+[ring[0]]],fill=color,width=2)
    (ROOT/'johannesbergbuild/mapping/lm-review-back9-turf.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n','utf-8')
    for window,img in overlays.items():img.save(CACHE/(window+'-back9-turf-reviewed.png'))
    print(json.dumps(dict(features=len(result['features']),unresolved=len(result['unresolved']))))

if __name__=='__main__':main()
